effect.frag.content:
uniform float u_amount;
vec4 sourceAt(vec2 uv) {
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  return texture(u_source, uv);
}
vec4 over(vec4 front, vec4 back) { return front + back * (1.0 - front.a); }
void main() {
  vec4 color = vec4(0.0);
  for (int i = 0; i < 4; i++) {
    float phase = fract(u_progress + float(i) * 0.25) * 4.0;
    float edge = floor(phase), f = fract(phase);
    vec2 center = edge < 1.0 ? vec2(mix(-1.0, 1.0, f), -1.0) : edge < 2.0 ? vec2(1.0, mix(-1.0, 1.0, f)) : edge < 3.0 ? vec2(mix(1.0, -1.0, f), 1.0) : vec2(-1.0, mix(1.0, -1.0, f));
    color = over(sourceAt((v_uv - 0.5 - center * (0.15 + u_amount * 0.12)) / 0.4 + 0.5), color);
  }
  fragColor = color;
}
